package com.campusiq.platform.strategy; import com.campusiq.platform.entity.Platform; import org.junit.jupiter.api.Test; import java.util.List; import static org.assertj.core.api.Assertions.assertThat; import static org.mockito.Mockito.*; class PlatformStrategyFactoryTest {@Test void returnsStrategiesByPlatform(){var l=mock(PlatformProfileStrategy.class);var f=mock(PlatformProfileStrategy.class);var c=mock(PlatformProfileStrategy.class);var g=mock(PlatformProfileStrategy.class);when(l.getPlatform()).thenReturn(Platform.LEETCODE);when(f.getPlatform()).thenReturn(Platform.CODEFORCES);when(c.getPlatform()).thenReturn(Platform.CODECHEF);when(g.getPlatform()).thenReturn(Platform.GEEKSFORGEEKS);var factory=new PlatformStrategyFactory(List.of(l,f,c,g));assertThat(factory.get(Platform.LEETCODE)).isSameAs(l);assertThat(factory.get(Platform.CODEFORCES)).isSameAs(f);assertThat(factory.get(Platform.CODECHEF)).isSameAs(c);assertThat(factory.get(Platform.GEEKSFORGEEKS)).isSameAs(g);}}
